from collections import Counter
def transform(g):
    g=[r[:] for r in g]
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    div=None
    for j in range(w):
        if len(set(g[i][j] for i in range(h)))==1 and g[0][j]!=bg: div=('v',j,g[0][j]); break
    if div is None:
        for i in range(h):
            if len(set(g[i]))==1 and g[i][0]!=bg: div=('h',i,g[i][0]); break
    kind,pos,line=div
    cells=[(i,c) for i in range(h) for c in range(w) if g[i][c]!=line and g[i][c]!=bg]
    cols=sorted(set(c for i,c in cells)); rows=sorted(set(i for i,c in cells))
    colsc=[c for i,c in cells]; rowsc=[i for i,c in cells]
    shapecol=Counter(colsc).most_common(1)[0][0]
    if kind=='v':
        dirn = 1 if cols[0]>pos else -1
        side = pos + dirn*(len(cols)+1)
        for i in range(h): g[i][side]=8
        if cols[0]<=side<=cols[-1]:  # bar overlaps bbox: fill rest of bbox with shape color
            for i in rows:
                for c in range(cols[0],cols[-1]+1):
                    if c!=side: g[i][c]=shapecol
    else:
        dirn = 1 if rows[0]>pos else -1
        side = pos + dirn*(len(rows)+1)
        for j in range(w): g[side][j]=8
        if rows[0]<=side<=rows[-1]:
            for j in cols:
                for i in range(rows[0],rows[-1]+1):
                    if i!=side: g[i][j]=shapecol
    return g
